interface VokState {
  state: 'init' | 'pex' | 'dor';
}

const initialState: VokState = {
  state: 'init',
};

type VokOperation = 'advanceVok' | 'recoverVok';

const applyVokOperation = (
  state: VokState,
  operation: VokOperation
): VokState => {
